  assert(/robocopy \$claudeHome \$backupDir \/E \/R:1 \/W:1 \/XJ/.test(blk),
    'бэкап с /XJ — не рекурсирует по junction внутри ~/.claude (иначе уходит в профиль/сетевую цель и растёт бесконечно)');
