      exe(bin + '/dscl', '#!/bin/sh\nexit 1\n');
      ['zsh', 'bash', 'fish'].forEach((n) => exe(bin + '/' + n, '#!/bin/sh\nexit 0\n'));
      const r = libRun(['zsh', 'bash', 'fish'].map((n) => 'echo "' + n + '=$(SHELL="' + mp(bin) + '/' + n + '" hm_login_profile_name)"').join('\n'), bin, { HOME: base });
      const out = r.stdout || '';
